  const ball = { x: 126, y: 108, r: 7, vx: 0, vy: -100 };
  const destroyed = brickHit(ball, [brick], 126, 140);
  assert.deepEqual(destroyed, [brick]);
  assert.equal(brick.alive, false);
  assert.equal(ball.vy, 100, 'moving up (negative vy) bounces back DOWN');
  assert.equal(ball.vx, 0, 'side component untouched');
  assert.equal(ball.y, 117, 'pushed out below the brick (90 + 20 + r)');
  assert.equal(ball.x, 126);
});

test('brickHit: side-face hit flips vx and pushes the ball out sideways', () => {
  const brick = makeBrick();
  const ball = { x: 100, y: 100, r: 7, vx: 50, vy: 0 };
  const destroyed = brickHit(ball, [brick], 60, 100);
  assert.deepEqual(destroyed, [brick]);
  assert.equal(ball.vx, -50, 'moving right (positive vx) bounces back LEFT');
  assert.equal(ball.vy, 0, 'vertical component untouched');
  assert.equal(ball.x, 83, 'pushed out to the left of the brick (90 - r)');
  assert.equal(ball.y, 100);
});

test('brickHit: corner hit (equal penetration) flips both components', () => {
  const brick = makeBrick();
  const ball = { x: 110, y: 90, r: 7, vx: 50, vy: -50 };
  const destroyed = brickHit(ball, [brick], 70, 130);
  assert.deepEqual(destroyed, [brick]);
  assert.equal(ball.vx, -50, 'horizontal flipped');
  assert.equal(ball.vy, 50, 'vertical flipped');
  assert.equal(ball.x, 83, 'pushed out left of the brick');
  assert.equal(ball.y, 117, 'pushed out below the brick');
});

test('brickHit: seam overlap destroys both bricks but bounces exactly once', () => {
  const top = makeBrick();
  const bottom = makeBrick({ y: 118 }); // 8 px gap, ball r=7 overlaps both
  const ball = { x: 110, y: 114, r: 7, vx: 50, vy: 0 };
  const destroyed = brickHit(ball, [top, bottom], 60, 114);
  assert.equal(destroyed.length, 2);
  assert.equal(top.alive, false);
  assert.equal(bottom.alive, false);
  assert.equal(ball.vx, -50, 'flipped exactly once, not twice (no cancel-out)');
  assert.equal(ball.vy, 0);
});

test('brickHit: sweep catches a fast ball that jumps over a brick in one step', () => {
  const brick = makeBrick();
  // Level-6 worst case: 35.5 px in one 50 ms stutter vs 34 px to fully cross
  // a brick (BRICK_H 20 + diameter 14). Discrete detection misses entirely.
  const ball = { x: 126, y: 82.5, r: 7, vx: 0, vy: -35.5 };
  const destroyed = brickHit(ball, [brick], 126, 118);
  assert.equal(destroyed.length, 1);
  assert.equal(ball.vy, 35.5, 'bounces back DOWN off the bottom face');
  assert.equal(ball.y, 117, 'pushed out below the brick');
});

test('brickHit: no overlap leaves bricks alive and the ball untouched', () => {
  const brick = makeBrick();
  const ball = { x: 300, y: 300, r: 7, vx: 10, vy: -10 };
  const destroyed = brickHit(ball, [brick], 299, 301);
  assert.deepEqual(destroyed, []);
  assert.equal(brick.alive, true);
  assert.equal(ball.vx, 10);
  assert.equal(ball.vy, -10);
  assert.equal(ball.x, 300);
  assert.equal(ball.y, 300);
});

