// True if the ball (circle approximated by its box) overlaps the brick.
// Simple AABB test: it only says WHETHER the ball and the brick overlap, not
// WHICH face was hit. The actual bounce lives in brickHit() below.
export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// First point along the swept path (px,py)->(ball.x,ball.y) that overlaps the
// brick, or null if the path clears it. Sampling every `ball.r` pixels keeps
// the worst stuttered step (35.5 px at level 6) well under the 34 px needed to
// cross a brick, so a fast ball cannot tunnel through (issue #1). Returns a
// copy — never mutates the ball.
function sweptHit(ball, brick, px, py) {
  if (px === undefined || py === undefined) {
    return collides(ball, brick) ? { x: ball.x, y: ball.y } : null;
  }
  const dx = ball.x - px;
  const dy = ball.y - py;
  const dist = Math.hypot(dx, dy);
  const steps = Math.max(1, Math.ceil(dist / ball.r));
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const sx = px + dx * t;
    const sy = py + dy * t;
    if (
      sx + ball.r > brick.x &&
      sx - ball.r < brick.x + brick.w &&
      sy + ball.r > brick.y &&
      sy - ball.r < brick.y + brick.h
    ) {
      return { x: sx, y: sy };
    }
  }
  return null;
}

// The axis with the *smaller* penetration is the face that was hit (issue #1):
// flip vy on a top/bottom hit, vx on a side hit, both on an equal-penetration
// corner hit. The ball is then pushed back out of the brick rectangle so it
// cannot still overlap on the next frame (no sticky re-flip). The ball is
// expected to already sit on the collision point when this is called.
function resolveBounce(ball, brick) {
  const overlapLeft = ball.x + ball.r - brick.x;
  const overlapRight = brick.x + brick.w - (ball.x - ball.r);
  const overlapTop = ball.y + ball.r - brick.y;
  const overlapBottom = brick.y + brick.h - (ball.y - ball.r);
  const penX = Math.min(overlapLeft, overlapRight);
  const penY = Math.min(overlapTop, overlapBottom);

  const EPS = 0.5; // treat nearly-equal penetrations as a corner hit
  if (penX < penY - EPS) {
    // Side face: flip the horizontal component only.
    if (overlapLeft < overlapRight) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    ball.vx = -ball.vx;
  } else if (penY < penX - EPS) {
    // Top/bottom face: flip the vertical component only.
    if (overlapTop < overlapBottom) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vy = -ball.vy;
  } else {
    // Corner: equal penetration in both axes, a diagonal hit — flip both.
    if (overlapLeft < overlapRight) {
      ball.x = brick.x - ball.r;
    } else {
      ball.x = brick.x + brick.w + ball.r;
    }
    if (overlapTop < overlapBottom) {
      ball.y = brick.y - ball.r;
    } else {
      ball.y = brick.y + brick.h + ball.r;
    }
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
  }
}

// Swept-penetration at a point, used to pick the shallowest (first) hit when
// a seam overlaps several bricks in the same pass.
function penetrationAt(brick, x, y, r) {
  const left = x + r - brick.x;
  const right = brick.x + brick.w - (x - r);
  const top = y + r - brick.y;
  const bottom = brick.y + brick.h - (y - r);
  return Math.min(left, right) + Math.min(top, bottom);
}

// Resolves brick collisions for one frame. Destroys every brick on the ball's
// swept path, then applies exactly ONE bounce against the shallowest hit — the
// grid gap (8 px) is smaller than the ball (14 px), so a seam overlaps two
// bricks in the same pass, and a second flip would cancel the first (issue #1).
// Returns the destroyed bricks (already marked `alive: false`) so the caller
// can score them.
export function brickHit(ball, bricks, prevX, prevY) {
  const hits = [];
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const point = sweptHit(ball, brick, prevX, prevY);
    if (!point) continue;
    brick.alive = false;
    hits.push({ brick, point });
  }
  if (hits.length === 0) return [];

  hits.sort(
    (a, b) => penetrationAt(a.brick, a.point.x, a.point.y, ball.r) - penetrationAt(b.brick, b.point.x, b.point.y, ball.r)
  );
  const { brick, point } = hits[0];
  ball.x = point.x;
  ball.y = point.y;
  resolveBounce(ball, brick);
  return hits.map((h) => h.brick);
}

