+// First point along the swept path (px,py)->(ball.x,ball.y) that overlaps the
+// brick, or null if the path clears it. Sampling every `ball.r` pixels keeps
+// the worst stuttered step (35.5 px at level 6) well under the 34 px needed to
+// cross a brick, so a fast ball cannot tunnel through (issue #1). Returns a
+// copy — never mutates the ball.
+function sweptHit(ball, brick, px, py) {
+  if (px === undefined || py === undefined) {
+    return collides(ball, brick) ? { x: ball.x, y: ball.y } : null;
+  }
+  const dx = ball.x - px;
+  const dy = ball.y - py;
+  const dist = Math.hypot(dx, dy);
+  const steps = Math.max(1, Math.ceil(dist / ball.r));
+  for (let i = 0; i <= steps; i++) {
+    const t = i / steps;
+    const sx = px + dx * t;
+    const sy = py + dy * t;
+    if (
+      sx + ball.r > brick.x &&
+      sx - ball.r < brick.x + brick.w &&
+      sy + ball.r > brick.y &&
+      sy - ball.r < brick.y + brick.h
+    ) {
+      return { x: sx, y: sy };
+    }
+  }
+  return null;
+}
+
+// The axis with the *smaller* penetration is the face that was hit (issue #1):
+// flip vy on a top/bottom hit, vx on a side hit, both on an equal-penetration
+// corner hit. The ball is then pushed back out of the brick rectangle so it
+// cannot still overlap on the next frame (no sticky re-flip). The ball is
+// expected to already sit on the collision point when this is called.
+function resolveBounce(ball, brick) {
+  const overlapLeft = ball.x + ball.r - brick.x;
+  const overlapRight = brick.x + brick.w - (ball.x - ball.r);
+  const overlapTop = ball.y + ball.r - brick.y;
+  const overlapBottom = brick.y + brick.h - (ball.y - ball.r);
+  const penX = Math.min(overlapLeft, overlapRight);
+  const penY = Math.min(overlapTop, overlapBottom);
