+  const EPS = 0.5; // treat nearly-equal penetrations as a corner hit
+  if (penX < penY - EPS) {
+    // Side face: flip the horizontal component only.
+    if (overlapLeft < overlapRight) {
+      ball.x = brick.x - ball.r;
+    } else {
+      ball.x = brick.x + brick.w + ball.r;
+    }
+    ball.vx = -ball.vx;
+  } else if (penY < penX - EPS) {
+    // Top/bottom face: flip the vertical component only.
+    if (overlapTop < overlapBottom) {
