+    hits.push({ brick, point });
+  }
+  if (hits.length === 0) return [];
+
+  hits.sort(
+    (a, b) => penetrationAt(a.brick, a.point.x, a.point.y, ball.r) - penetrationAt(b.brick, b.point.x, b.point.y, ball.r)
+  );
+  const { brick, point } = hits[0];
+  ball.x = point.x;
+  ball.y = point.y;
+  resolveBounce(ball, brick);
+  return hits.map((h) => h.brick);
