edits.newText:
export function createState(level = 1) {
  const speed = ballSpeed(level);
  const ball = { x: WIDTH / 2, y: PADDLE_Y - BALL_R - 2, r: BALL_R, vx: speed * 0.5, vy: -speed };
  // px/py remember where the ball was before the last step(): brickHit()
  // sweeps between the two positions so fast balls cannot tunnel through.
  ball.px = ball.x;
  ball.py = ball.y;
  return {
    level,
    lives: 3,
    score: 0,
    combo: 0,
    best: 0,
    running: false,
    paddle: { x: (WIDTH - PADDLE_W) / 2, y: PADDLE_Y, w: PADDLE_W, h: PADDLE_H },
    ball,
    bricks: makeBricks(level),
  };
}

