export function step(state, dt) {
  const { ball, paddle } = state;

  // Remember the pre-move position: brickHit() sweeps from here.
  ball.px = ball.x;
  ball.py = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

