import('./game/neon.js').then(({ createState, step, frame, ballSpeed }) => {
  const ctx = new Proxy({}, { get: (t, p) => (p === 'arc' || p === 'fillRect' || p === 'beginPath' || p === 'fill' || p === 'fillText') ? () => {} : (t[p] ?? 0) });
  const state = createState(1);
  state.running = true;
  // aim straight up at a brick and run several frames
  state.ball.x = 320; state.ball.y = 200; state.ball.vx = 0; state.ball.vy = -100;
  for (let i = 0; i < 120 && state.lives > 0; i++) {
    const lost = step(state, 1/60);
    if (lost) break;
    frame(ctx, state);
  }
  const dead = state.bricks.filter(b => !b.alive).length;
  console.log('destroyed bricks:', dead, '/', state.bricks.length);
  console.log('ball now at y=', state.ball.y.toFixed(1), 'vy=', state.ball.vy.toFixed(1));
  console.log('score:', state.score);
});
"
